import { useEffect, useId, useRef, useState, type ComponentProps } from "react";
import { Markdown } from "./markdown";
import { Textarea } from "./textarea";
import { cn } from "./utils";

type MarkdownEditorMode = "edit" | "split" | "read";

type MarkdownEditorProps = Omit<
    ComponentProps<"section">, "children" | "defaultValue" | "onChange"
> & {
    label: string;
    value: string;
    onValueChange: (value: string) => void;
    name?: string;
    description?: string;
    error?: string;
    placeholder?: string;
    rows?: number;
    required?: boolean;
    disabled?: boolean;
    readOnly?: boolean;
    defaultShowPreview?: boolean;
    syntax?: "legacy" | "gfm";
    mode?: MarkdownEditorMode;
    defaultMode?: MarkdownEditorMode;
    onModeChange?: (mode: MarkdownEditorMode) => void;
    syncScroll?: boolean;
};

function MarkdownEditor({
    label,
    value,
    onValueChange,
    name,
    description,
    error,
    placeholder,
    rows = 10,
    required = false,
    disabled = false,
    readOnly = false,
    defaultShowPreview = true,
    syntax = "legacy",
    mode,
    defaultMode,
    onModeChange,
    syncScroll = true,
    className,
    ...props
}: MarkdownEditorProps) {
    const inputId = useId();
    const descriptionId = useId();
    const errorId = useId();
    const previewId = useId();
    const previewTitleId = useId();
    const [legacyPreview, setLegacyPreview] = useState(defaultShowPreview);
    const [localMode, setLocalMode] = useState<MarkdownEditorMode>(
        defaultMode ?? "split",
    );
    const inputRef = useRef<HTMLTextAreaElement>(null);
    const previewRef = useRef<HTMLDivElement>(null);
    const scrolling = useRef<HTMLElement | null>(null);
    const scrollFrame = useRef<number | null>(null);
    const workbench = mode !== undefined || defaultMode !== undefined;
    const currentMode = mode ?? localMode;
    const showPreview = workbench ? currentMode !== "edit" : legacyPreview;

    useEffect(() => () => {
        if (scrollFrame.current !== null) cancelAnimationFrame(scrollFrame.current);
    }, []);

    function changeMode(next: MarkdownEditorMode) {
        if (mode === undefined) setLocalMode(next);
        onModeChange?.(next);
    }

    function syncPanels(source: HTMLElement, target: HTMLElement | null) {
        if (!workbench || !syncScroll || currentMode !== "split" || !target ||
            (scrolling.current && scrolling.current !== source)) return;
        scrolling.current = source;
        const available = source.scrollHeight - source.clientHeight;
        const ratio = available > 0 ? source.scrollTop / available : 0;
        target.scrollTop = ratio * Math.max(0,
            target.scrollHeight - target.clientHeight);
        if (scrollFrame.current !== null) cancelAnimationFrame(scrollFrame.current);
        scrollFrame.current = requestAnimationFrame(() => {
            scrolling.current = null;
            scrollFrame.current = null;
        });
    }

    function showCaretLine() {
        if (!workbench || !syncScroll || currentMode !== "split") return;
        const input = inputRef.current;
        const preview = previewRef.current;
        if (!input || !preview) return;
        const line = value.slice(0, input.selectionStart).split("\n").length;
        const elements = [...preview.querySelectorAll<HTMLElement>(
            "[data-source-line]",
        )];
        const target = elements.filter((element) =>
            Number(element.dataset.sourceLine) <= line).at(-1);
        if (target) {
            preview.scrollTop += target.getBoundingClientRect().top -
                preview.getBoundingClientRect().top;
        }
    }

    if (typeof label !== "string" || !label.trim()) {
        throw new Error("MarkdownEditor requires a label.");
    }
    if (typeof value !== "string") {
        throw new TypeError("MarkdownEditor value must be a string.");
    }
    if (typeof onValueChange !== "function") {
        throw new TypeError("MarkdownEditor requires onValueChange.");
    }
    if (!Number.isInteger(rows) || rows < 1) {
        throw new RangeError("MarkdownEditor rows must be a positive integer.");
    }
    if (!["edit", "split", "read"].includes(currentMode)) {
        throw new RangeError("MarkdownEditor mode is not supported.");
    }
    if (mode !== undefined && !onModeChange) {
        throw new Error("Controlled MarkdownEditor mode requires onModeChange.");
    }
    if (name !== undefined &&
        (typeof name !== "string" || !name.trim())) {
        throw new Error("MarkdownEditor name must not be empty.");
    }

    const describedBy = [
        description ? descriptionId : null,
        error ? errorId : null,
    ].filter(Boolean).join(" ") || undefined;

    return (
        <section {...props} data-ui="markdown-editor" className={cn(
            "min-w-0 overflow-hidden rounded-sm border border-border " +
            "bg-surface text-foreground",
            className,
        )}>
            <div data-slot="editor-header" className={
                "flex flex-wrap items-center justify-between gap-2 " +
                "border-b border-border bg-surface-subtle " +
                "px-[var(--space-3)] py-[var(--space-2)]"
            }>
                <label htmlFor={inputId} className="text-sm font-medium">
                    {label}
                </label>
                {workbench ? <div role="group" aria-label="문서 표시 모드"
                    className="flex flex-wrap gap-1">
                    {(["edit", "split", "read"] as const).map((item) => (
                        <button key={item} type="button"
                            aria-pressed={currentMode === item}
                            onClick={() => changeMode(item)}
                            className={
                                "rounded-sm border border-border px-3 py-1 " +
                                "text-xs aria-pressed:bg-surface " +
                                "aria-pressed:font-semibold " +
                                "focus-visible:outline-2 focus-visible:outline-focus"
                            }>{item === "edit" ? "편집" : item === "split"
                                ? "분할" : "읽기"}</button>
                    ))}
                </div> : <button type="button" aria-controls={previewId}
                    aria-expanded={showPreview}
                    onClick={() => setLegacyPreview((current) => !current)}
                    className={
                        "rounded-sm border border-border bg-surface " +
                        "px-3 py-1 text-xs hover:bg-surface-subtle " +
                        "focus-visible:outline-2 focus-visible:outline-focus"
                    }>
                    {showPreview ? "미리보기 숨기기" : "미리보기 표시"}
                </button>}
            </div>
            <div data-slot="editor-columns" className={cn(
                "grid min-w-0",
                showPreview && (!workbench || currentMode === "split") &&
                    "lg:grid-cols-2",
            )}>
                <div data-slot="editor-pane"
                    hidden={workbench && currentMode === "read"}
                    className={cn(
                    "min-w-0 p-[var(--space-3)]",
                    showPreview && "border-b border-border lg:border-b-0 " +
                        "lg:border-r",
                )}>
                    <Textarea ref={inputRef} id={inputId} name={name} value={value}
                        rows={rows} required={required} disabled={disabled}
                        readOnly={readOnly || (workbench && currentMode === "read")}
                        placeholder={placeholder}
                        aria-describedby={describedBy}
                        aria-invalid={!!error}
                        onChange={(event) =>
                            onValueChange(event.currentTarget.value)}
                        onScroll={(event) => syncPanels(
                            event.currentTarget, previewRef.current,
                        )}
                        onSelect={showCaretLine}
                        className={cn(
                            "block min-h-0 resize-y font-mono text-xs " +
                            "leading-6", workbench && "max-h-96 overflow-auto",
                        )} />
                </div>
                <div id={previewId} ref={previewRef} hidden={!showPreview}
                    data-slot="editor-preview"
                    role="region" aria-labelledby={previewTitleId}
                    className={cn("min-w-0 p-[var(--space-3)]",
                        workbench && "max-h-96 overflow-auto")}
                    onScroll={(event) => syncPanels(
                        event.currentTarget, inputRef.current,
                    )}
                    onClick={(event) => {
                        if (!workbench || currentMode !== "split" ||
                            !(event.target instanceof HTMLElement) ||
                            event.target.closest("a,button,input")) return;
                        const line = Number(event.target.closest<HTMLElement>(
                            "[data-source-line]",
                        )?.dataset.sourceLine);
                        if (!Number.isInteger(line) || line < 1) return;
                        const offset = value.split("\n").slice(0, line - 1)
                            .reduce((total, text) => total + text.length + 1, 0);
                        inputRef.current?.focus();
                        inputRef.current?.setSelectionRange(offset, offset);
                    }}>
                    <h3 id={previewTitleId}
                        className="mb-3 mt-0 text-xs font-medium text-muted">
                        미리보기
                    </h3>
                    {value.trim()
                        ? <Markdown source={value} syntax={syntax}
                            headingPrefix={`${inputId}-`} />
                        : <p className="m-0 text-sm text-muted">
                            입력한 내용이 여기에 표시됩니다.
                        </p>}
                </div>
            </div>
            {(description || error) && (
                <div data-slot="editor-footer" className={
                    "grid gap-1 border-t border-border " +
                    "px-[var(--space-3)] py-[var(--space-2)]"
                }>
                    {description && <p id={descriptionId}
                        className="m-0 text-xs text-muted">
                        {description}
                    </p>}
                    {error && <p id={errorId} role="alert"
                        className="m-0 text-xs text-danger">
                        {error}
                    </p>}
                </div>
            )}
        </section>
    );
}

export { MarkdownEditor };
export type { MarkdownEditorMode, MarkdownEditorProps };
